#include<bits/stdc++.h>

using namespace std;

void solve() {
    int n, m, l;
    cin >> n >> m >> l;

    int const inf = 2e9 + 1;
    int sum = 0, min_odd = inf;
    vector<int> a(l);
    for (int i = 0; i < l; ++i) {
        cin >> a[i];
        sum += a[i];
        if (a[i] % 2) {
            min_odd = min(min_odd, a[i]);
        }
    }

    vector adj(n, vector<int>());
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<array<int, 2>> dist(n, {inf, inf});
    queue<pair<int, int>> q;
    q.push({0, 0});
    dist[0][0] = 0;
    while (q.size()) {
        auto [u, p] = q.front();
        q.pop();
        for (auto v : adj[u]) {
            if (dist[v][!p] > dist[u][p] + 1) {
                dist[v][!p] = dist[u][p] + 1;
                q.push({v, !p});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        bool found = 0;
        for (int p = 0; p < 2; ++p) {
            int s = sum - (p == sum % 2 ? 0 : min_odd);
            if (dist[i][p] <= s) {
                found = 1;
            }
        }
        cout << found;
    }
    cout << "\n";
}

int main() {
    ios::sync_with_stdio(0), cin.tie(0);
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define debug(x) cout << #x << " = " << x << "\n";
#define vdebug(a) cout << #a << " = "; for(auto x: a) cout << x << " "; cout << "\n";
mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
int uid(int a, int b) { return uniform_int_distribution<int>(a, b)(rng); }
ll uld(ll a, ll b) { return uniform_int_distribution<ll>(a, b)(rng); }

const int MOD = 998244353;

template<ll mod> // template was not stolen from https://codeforces.com/profile/SharpEdged
struct modnum {
    static constexpr bool is_big_mod = mod > numeric_limits<int>::max();

    using S = conditional_t<is_big_mod, ll, int>;
    using L = conditional_t<is_big_mod, __int128, ll>;

    S x;

    modnum() : x(0) {}
    modnum(ll _x) {
        _x %= static_cast<ll>(mod);
        if (_x < 0) { _x += mod; }
        x = _x;
    }

    modnum pow(ll n) const {
        modnum res = 1;
        modnum cur = *this;
        while (n > 0) {
            if (n & 1) res *= cur;
            cur *= cur;
            n /= 2;
        }
        return res;
    }
    modnum inv() const { return (*this).pow(mod-2); }

    modnum& operator+=(const modnum& a){
        x += a.x;
        if (x >= mod) x -= mod;
        return *this;
    }
    modnum& operator-=(const modnum& a){
        if (x < a.x) x += mod;
        x -= a.x;
        return *this;
    }
    modnum& operator*=(const modnum& a){
        x = static_cast<L>(x) * a.x % mod;
        return *this;
    }
    modnum& operator/=(const modnum& a){ return *this *= a.inv(); }

    friend modnum operator+(const modnum& a, const modnum& b){ return modnum(a) += b; }
    friend modnum operator-(const modnum& a, const modnum& b){ return modnum(a) -= b; }
    friend modnum operator*(const modnum& a, const modnum& b){ return modnum(a) *= b; }
    friend modnum operator/(const modnum& a, const modnum& b){ return modnum(a) /= b; }

    friend bool operator==(const modnum& a, const modnum& b){ return a.x == b.x; }
    friend bool operator!=(const modnum& a, const modnum& b){ return a.x != b.x; }
    friend bool operator<(const modnum& a, const modnum& b){ return a.x < b.x; }

    friend ostream& operator<<(ostream& os, const modnum& a){ os << a.x; return os; }
    friend istream& operator>>(istream& is, modnum& a) { ll x; is >> x; a = modnum(x); return is; }
};

using mint = modnum<MOD>;

struct Combi{
    vector<mint> _fac, _ifac;
    int n;

    Combi() {
        n = 1;
        _fac.assign(n + 1, 1);
        _ifac.assign(n + 1, 1);
    }

    void check_size(int m){
        int need = n;
        while (need < m) need *= 2;
        m = need;
        if (m <= n) return;

        _fac.resize(m + 1);
        _ifac.resize(m + 1);
        for (int i = n + 1; i <= m; i++) _fac[i] = i * _fac[i - 1];

        _ifac[m] = _fac[m].inv();
        for (int i = m - 1; i > n; i--) _ifac[i] = _ifac[i + 1] * (i + 1);
        n = m;
    }

    mint fac(int m){
        check_size(m);
        return _fac[m];
    }

    mint ifac(int m){
        check_size(m);
        return _ifac[m];
    }

    mint ncr(int n, int r){
        if (n < r || r < 0) return 0;

        return fac(n) * ifac(n - r) * ifac(r);
    }

    mint npr(int n, int r){
        if (n < r || r < 0) return 0;

        return fac(n) * ifac(n - r);
    }
} comb;

void solve(){
    int n, k;
    cin >> n >> k;

    string s;
    cin >> s;

    vector<vector<mint>> dp(n, vector<mint>(k + 1));
    dp[n - 1][0] = 1;
    if (s[n - 1] == '0')
        dp[n - 1][1] = 1;

    for (int i = n - 2; i >= 0; i--){
        for (int j = 0; j <= k; j++){
            for (int c = 0; j + c <= k; c++){
                int spaces = (j + c + (s[i] == '0')) / 2;
                dp[i][j + c] += dp[i + 1][j] * comb.ncr(spaces, c);
            }
        }
    }

    cout << dp[0][k] << "\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;
    while (t--) solve();
}

#include<bits/stdc++.h>

using namespace std;

using i64 = long long;

constexpr int inf = 1e9;
array<int, 8> dx{0, 0, 1, -1, 1, 1, -1, -1};
array<int, 8> dy{1, -1, 0, 0, -1, 1, -1, 1};

void solve() {
    int n, r, k;
    cin >> n >> r >> k;
    --r;

    vector a(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
        }
    }

    vector b(n, vector<int>(n));
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        for (int j = 0; j < n; ++j) {
            b[i][j] = s[j] - '0';
        }
    }

    auto in = [&](int i, int j) {
        return (0 <= i && i < n && 0 <= j && j < n);
    };

    priority_queue<array<int, 3>, vector<array<int, 3>>, greater<>> pq;
    pq.push({a[0][0], 0, 0});
    vector dis(n, vector<int>(n, inf));
    dis[0][0] = a[0][0];
    while (pq.size()) {
        auto [mx, i, j] = pq.top();
        pq.pop();
        if (dis[i][j] != mx) {
            continue;
        }
        for (int dir = 0; dir < 4; ++dir) {
            int ni = i + dx[dir];
            int nj = j + dy[dir];
            if (in(ni, nj) && dis[ni][nj] > max(mx, a[ni][nj])) {
                int nmx = max(mx, a[ni][nj]);
                dis[ni][nj] = nmx;
                pq.push({nmx, ni, nj});
            }
        }
    }
    int mouf = dis[r][n - 1];

    vector dont(n, vector<int>(n));
    auto run = [&](auto &&run, int i, int j) -> void {
        for (int dir = 0; dir < 8; ++dir) {
            int ni = i + dx[dir];
            int nj = j + dy[dir];
            if (in(ni, nj) && dont[ni][nj] == 0) {
                dont[ni][nj] = 1;
                if (a[ni][nj] > mouf) {
                    run(run, ni, nj);
                }
            }
        }
    };

    for (int j = 0; j < n; ++j) {
        dont[0][j] = 1;
        if (a[0][j] > mouf) {
            run(run, 0, j);
        }
    }
    for (int i = 0; i <= r; ++i) {
        dont[i][n - 1] = 1;
        if (a[i][n - 1] > mouf) {
            run(run, i, n - 1);
        }
    }

    int L = 1, R = 2e6;
    while (L <= R) {
        int mid = (L + R) / 2;
        for (int j = 0; j < n; ++j) {
            if ((mid > mouf && dont[n - 1][j]) || (mid > a[n - 1][j] && b[n - 1][j] == 0)) {
                continue;
            }
            pq.push({max(0, mid - a[n - 1][j]), n - 1, j});
        }
        for (int i = r; i < n; ++i) {
            if ((mid > mouf && dont[i][n - 1]) || (mid > a[i][n - 1] && b[i][n - 1] == 0)) {
                continue;
            }
            pq.push({max(0, mid - a[i][n - 1]), i, n - 1});
        }
        fill(dis.begin(), dis.end(), vector<int>(n, inf));
        while (pq.size()) {
            auto [cost, i, j] = pq.top();
            pq.pop();
            dis[i][j] = min(dis[i][j], cost);
            if (dis[i][j] != cost) {
                continue;
            }
            for (int dir = 0; dir < 8; ++dir) {
                int ni = i + dx[dir];
                int nj = j + dy[dir];
                if (in(ni, nj)) {
                    if ((mid > mouf && dont[ni][nj]) || (mid > a[ni][nj] && b[ni][nj] == 0)) {
                        continue;
                    }
                    if (dis[ni][nj] > cost + max(0, mid - a[ni][nj])) {
                        int ncost = cost + max(0, mid - a[ni][nj]);
                        dis[ni][nj] = ncost;
                        pq.push({ncost, ni, nj});
                    }
                }
            }
        }
        int minCost = inf;
        if (mid <= mouf) {
            for (int j = 0; j < n; ++j) {
                minCost = min(minCost, dis[0][j]);
            }
            for (int i = 0; i <= r; ++i) {
                minCost = min(minCost, dis[i][n - 1]);
            }
        }
        for (int i = 1; i < n; ++i) {
            minCost = min(minCost, dis[i][0]);
        }
        if (minCost <= k) {
            L = mid + 1;
        } else {
            R = mid - 1;
        }
    }

    cout << mouf << " " << R << "\n";
}

int main() {
    ios::sync_with_stdio(0), cin.tie(0);
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
}
